"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track data-slot="slider-track" className="relative h-2 w-full grow overflow-hidden rounded-full backdrop-blur-xl bg-foreground/[0.08] shadow-[inset_0_0_0.25rem_color-mix(in_oklch,var(--halo)_6%,transparent)]">
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full bg-gradient-to-t from-primary to-primary/85 shadow-[inset_0_0.0625rem_0_oklch(1_0_0/0.22)]" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb" key={index}
              className={cn(
                "block h-5 w-5 rounded-full",
                "bg-primary-foreground border border-foreground/20",
                "shadow-[0_0.125rem_0.25rem_-0.0625rem_color-mix(in_oklch,var(--shade)_35%,transparent),inset_0_0.0625rem_0_oklch(1_0_0/0.5)]",
                "transition-[box-shadow] duration-base",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                "hover:shadow-[0_0.1875rem_0.375rem_-0.0625rem_color-mix(in_oklch,var(--shade)_40%,transparent),inset_0_0.0625rem_0_oklch(1_0_0/0.5)]",
                "data-disabled:pointer-events-none data-disabled:opacity-50"
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
